// 12. Code: Build Final Summary — return result IDs and final status
const parsed = $('Code: Parse and Validate Summary/Actions').first().json;
const callbackRes = $('HTTP Request: Save Conversation Summary').first().json;

return [{
  json: {
    status: parsed.status,
    transcriptId: parsed.transcriptId,
    workflowRunId: parsed.workflowRunId,
    summaryId: callbackRes.summaryId || null,
    actionItemCount: parsed.actionItems ? parsed.actionItems.length : 0,
    sentiment: parsed.sentiment,
    intent: parsed.intent,
    completedAt: new Date().toISOString()
  }
}];
